using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// --- 1. Get strongly-typed JsonTypeInfo<T> ---
JsonTypeInfo<Person> typedInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person: {typedInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), typedInfo);
Console.WriteLine($"Serialized: {json}");

Person? p = JsonSerializer.Deserialize(json, typedInfo);
Console.WriteLine($"Deserialized: {p}");

// --- 2. Probe without throwing using TryGetTypeInfo ---
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {info!.Type.Name}");
}

// Now try a type that has NO resolver configured (empty resolver)
var restrictedOptions = new JsonSerializerOptions
{
    // A resolver that resolves nothing
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => throw new NotSupportedException() }
    }
};

// Use a bare resolver that always returns null to simulate "not available"
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // no resolvers → always null
};

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
{
    Console.WriteLine("Unexpected: found metadata");
}
else
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) on empty resolver: not available (no exception thrown)");
}

// record used for the demo
public record Person(string Name, int Age);

